        { title: "Knut Posse", publisher: "Svenskt biografiskt lexikon (Riksarkivet)", url: "https://sok.riksarkivet.se/sbl/Presentation.aspx?id=7380" },
        { title: "Svante Nilsson Sture", publisher: "Svenskt biografiskt lexikon (Riksarkivet)", url: "https://sok.riksarkivet.se/sbl/Artikel/34641" }
